const KEY='isekai-class32-v1';
const skills=[{id:'inspect',symbol:'◈',type:'ANALYSIS',name:'鑑定',desc:'触れた物の性質と、説明文に隠れた条件を読む。まずは情報を集めたい。',cost:'制約：生き物の心は読めない'},{id:'craft',symbol:'⌘',type:'CRAFT',name:'合成',desc:'二つの素材を、一つの道具に変える。レシピは実験で見つける。',cost:'制約：素材は消費される'},{id:'echo',symbol:'◎',type:'SUPPORT',name:'残響',desc:'直前に見た仲間の初級スキルを、一度だけ再現する。',cost:'制約：本人の同意が必要'}];
const plans=[{id:'together',symbol:'◇',type:'COOPERATE',name:'仲間と組む',desc:'結衣、蓮、澪、陽太と5人で動く。役割と苦手なことを共有する。',cost:'方針：連携・慎重'},{id:'rules',symbol:'≡',type:'INVESTIGATE',name:'ルールを聞く',desc:'光の案内人に、帰還条件とスキルの代償を質問する。',cost:'方針：情報・交渉'},{id:'scout',symbol:'⌁',type:'EXPLORE',name:'出口を調べる',desc:'見える範囲で扉と通路を調べる。単独で遠くへは行かない。',cost:'方針：探索・観察'}];
const routes=[{id:'water',symbol:'≈',type:'SURVIVAL',name:'水音の回廊',desc:'水を確保できるかもしれない。足元には新しい靴跡がある。',cost:'目的：水源と先客の確認'},{id:'archive',symbol:'▤',type:'KNOWLEDGE',name:'封印された書庫',desc:'扉には三つの窪み。カードの縁とよく似た形をしている。',cost:'目的：世界と帰還の手がかり'},{id:'camp',symbol:'△',type:'PREPARE',name:'広間に拠点を作る',desc:'残るクラスメイトと物資を数える。情報交換の場も必要だ。',cost:'目的：全員の安全と物資確認'}];
function initial(){return{version:1,turn:1,skill:null,plan:null,route:null,action:'',design:'',log:['2年3組の32人が、見知らぬ広間へ転移した。']}}
let state=initial(),selected=null,storageOK=true;
function valid(s){return s&&validHistory(s.history)&&s.version===1&&Number.isInteger(s.turn)&&s.turn>=1&&s.turn<=4&&Array.isArray(s.log)&&s.log.length<=30&&s.log.every(x=>typeof x==='string'&&x.length<4000)&&typeof s.action==='string'&&typeof s.design==='string'&&(s.turn===1?s.skill===null:skills.some(x=>x.id===s.skill))&&(s.turn<=2?s.plan===null:plans.some(x=>x.id===s.plan))&&(s.turn<=3?s.route===null:routes.some(x=>x.id===s.route))}
try{const raw=localStorage.getItem(KEY);if(raw){const loaded=JSON.parse(raw);if(valid(loaded))state=loaded;else storageOK=false}}catch{storageOK=false}
const $=id=>document.getElementById(id);const skill=()=>skills.find(x=>x.id===state.skill);const plan=()=>plans.find(x=>x.id===state.plan);const route=()=>routes.find(x=>x.id===state.route);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false}$('saveStatus').textContent=storageOK?'このブラウザに自動保存済み':'自動保存できません。「記録を保存」で保存してください'}
function sceneData(){return CURRENT_SCENE;}
function options(){return [];}
function render(){
 const d=sceneData();if($('teacherCondition'))$('teacherCondition').textContent=d.teacher?.condition||'未確認';$('turn').textContent=d.id;$('chapter').textContent='TURN '+d.id+' / ELDEN RING';$('storyTitle').textContent=d.title;
 $('storyText').replaceChildren(...d.text.map(t=>{const p=document.createElement('p');p.textContent=t;return p}));$('quote').textContent=d.quote;
 $('skill').textContent=d.teacher?.uniqueSkill||'未設定';$('approach').textContent=d.actions?.player||'次の方針はチャットで';$('items').textContent=(Array.isArray(d.teacher?.gear)?d.teacher.gear.join('・'):d.teacher?.gear||'未記録')+' ／ 特殊品：'+(d.teacher?.specialItem||'保留');
 $('choiceTitle').textContent='次にどうする？ 自由行動も可';$('choiceMeta').textContent='行動はチャットで';
 $('choices').replaceChildren(...d.cards.map(o=>{const card=document.createElement('article');card.className='card';const genre=document.createElement('small');genre.textContent=o.genre;const name=document.createElement('strong');name.textContent=o.name;const desc=document.createElement('p');desc.textContent=o.desc;const cost=document.createElement('p');cost.className='cost';cost.textContent=o.cost;card.append(genre,name,desc,cost);return card}));
 $('confirm').hidden=true;$('hint').textContent='行動・会話・設計の相談はチャットへ。'+(d.actions?.result||'現在の場面から次の行動を選んでください。');
 $('log').replaceChildren(...d.logEntries.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));
 const people=d.people;
 $('npcs').replaceChildren(...people.map(p=>{const div=document.createElement('div');div.className='npc';div.innerHTML='<div class="avatar">'+p[0]+'</div><div><strong>'+p[1]+'</strong><small>'+p[2]+'</small><p>'+p[3]+'</p></div>';return div}));
 $('freeAction').value=state.action;$('designNote').value=state.design;save();
}
function advance(){throw Error('行動はチャットで指定してください。画面では進行を確定しません。');}
function handoff(){return '「ゲーム知識で異世界転生してみた with Codex」の続きを一緒に作ってください。\n私はプレイヤー「私」であり、ゲーム全体の設計者です。Codexは進行役とNPCを担当。\n現在：TURN '+state.turn+'／'+sceneData().title+'\n固有スキル：'+(sceneData().teacher?.uniqueSkill||'未設定')+'\n方針：'+(sceneData().actions?.player||'未決定')+'\n目的地：'+(sceneData().destination?.current||'未決定')+'\n記録：\n'+state.log.join('\n')+'\n\n現在の場面：\n'+sceneData().text.join('\n')+'\n\n【プレイヤーの行動】\n'+(state.action||'相談して決めたい')+'\n\n【設計者としての要望】\n'+(state.design||'今の設定をベースに相談したい')+'\n\nこの内容をもとに物語とHTMLを更新してください。私の行動は勝手に確定せず、必要なら選択肢を提示してください。'}
$('handoff').onclick=()=>{$('handoffText').hidden=false;$('handoffText').value=handoff();$('handoffText').select()};$('freeAction').oninput=e=>{state.action=e.target.value;save()};$('designNote').oninput=e=>{state.design=e.target.value;save()};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,authoredScene:CURRENT_SCENE},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='isekai-turn-'+CURRENT_SCENE.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('ファイルが大きすぎます');const s=JSON.parse(await file.text());if(!valid(s))throw Error('この物語の記録ではありません');if(!confirm('現在の進行を、選んだ記録で置き換えますか？'))return;state=s;selected=null;rememberScene();render();$('handoffText').hidden=true;$('importStatus').textContent='記録を読み込みました。'}catch(err){$('importStatus').textContent='読み込めません：'+err.message}finally{e.target.value=''}};
const im=$('sceneImage');im.onload=()=>{im.hidden=false};im.onerror=()=>{im.hidden=true};im.src=CURRENT_SCENE.image;
const ctx=document.modelContext;if(ctx?.registerTool){for(const t of [{name:'read_adventure',description:'現在の物語と選択肢を読む',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state,scene:sceneData(),choices:options()})},{name:'advance_adventure',description:'プレイヤーが指定した現在の選択肢を確定し、次のターンに進む',inputSchema:{type:'object',properties:{choiceId:{type:'string'}},required:['choiceId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>advance(input?.choiceId)}]){try{Promise.resolve(ctx.registerTool(t)).catch(()=>{})}catch{}}}
rememberScene();render();

function validHistory(h){return h===undefined||(Array.isArray(h)&&h.length<=1000&&h.every(x=>x&&Number.isInteger(x.turn)&&typeof x.title==='string'&&typeof x.choice==='string'&&typeof x.quote==='string'&&typeof x.at==='string'&&Array.isArray(x.text)&&x.text.every(t=>typeof t==='string')&&x.snapshot&&valid({...x.snapshot,history:undefined})));}
function rememberScene(choice=''){
 const d=sceneData();state.history??=[];
 const signature=JSON.stringify([state.turn,state.skill,state.plan,state.route,d]);
 let entry=state.history.find(x=>x.signature===signature);
 if(!entry){const snapshot=JSON.parse(JSON.stringify({...state,history:undefined}));entry={signature,turn:state.turn,sceneId:d.id,image:d.image,cards:d.cards,title:d.title,text:[...d.text],quote:d.quote,choice:'',at:new Date().toISOString(),snapshot};state.history.push(entry);}
 if(choice)entry.choice=choice;
}
const journal=document.createElement('dialog');journal.className='journal';journal.setAttribute('aria-label','冒険の回想');
const closeJournal=document.createElement('button');closeJournal.textContent='閉じる';closeJournal.onclick=()=>journal.close();
const journalBody=document.createElement('div');journal.append(closeJournal,journalBody);document.body.append(journal);
const journalButton=document.createElement('button');journalButton.textContent='冒険を振り返る';journalButton.onclick=()=>{rememberScene();save();journalBody.replaceChildren();for(const entry of state.history){const section=document.createElement('section');const h=document.createElement('h2');h.textContent='TURN '+(entry.sceneId||entry.turn)+' ／ '+entry.title;section.append(h);for(const line of [...entry.text,entry.quote,entry.choice?'選択：'+entry.choice:'この場面で待機中']){const p=document.createElement('p');p.textContent=line;section.append(p);}journalBody.append(section);}journal.showModal();};
document.querySelector('.save-popover').prepend(journalButton);
const refreshButton=document.createElement('button');refreshButton.className='refresh-toggle';let refreshOn=true;
try{refreshOn=sessionStorage.getItem(KEY+'-refresh')!=='off'}catch{}
function refreshLabel(){refreshButton.textContent=refreshOn?'更新確認 30秒：ON':'自動更新：停止';refreshButton.setAttribute('aria-pressed',String(refreshOn));}
refreshButton.onclick=()=>{refreshOn=!refreshOn;try{sessionStorage.setItem(KEY+'-refresh',refreshOn?'on':'off')}catch{}refreshLabel();};refreshLabel();document.querySelector('footer').append(refreshButton);
const panes=['.story','aside','#choices'];
try{const view=JSON.parse(sessionStorage.getItem(KEY+'-view')||'null');if(view&&view.sceneId===CURRENT_SCENE.id){if(options().some(o=>o.id===view.selected)){selected=view.selected;render();}requestAnimationFrame(()=>{panes.forEach((selector,i)=>{const el=document.querySelector(selector);if(el){el.scrollTop=view.scroll?.[i]?.top||0;el.scrollLeft=view.scroll?.[i]?.left||0}})});}}catch{}
let interactionAt=0;for(const type of ['pointerdown','keydown','wheel','touchstart'])document.addEventListener(type,()=>{interactionAt=Date.now()},{passive:true});
window.IsekaiLiveRefresh?.start({page:'main',enabled:()=>refreshOn,images:()=>[CURRENT_SCENE.image],beforeReload:()=>{rememberScene();save();if(!storageOK)return false;try{sessionStorage.setItem(KEY+'-view',JSON.stringify({turn:state.turn,sceneId:CURRENT_SCENE.id,selected,scroll:panes.map(selector=>{const el=document.querySelector(selector);return{top:el?.scrollTop||0,left:el?.scrollLeft||0}})}));}catch{return false}}});

const gearDialog=document.createElement('dialog');gearDialog.className='journal';gearDialog.setAttribute('aria-label','装備と固有能力');
const gearClose=document.createElement('button');gearClose.textContent='閉じる';gearClose.onclick=()=>gearDialog.close();gearDialog.append(gearClose);
const gearIntro=document.createElement('p');gearIntro.textContent='現在のレベル・能力値・装備を表示しています。原作を参考にした卓用の成長・能力設定です。先生：Lv.'+(CURRENT_SCENE.teacher?.level??'未設定')+' ／ 固有能力：'+(CURRENT_SCENE.teacher?.uniqueSkill||'未設定')+'。特殊品枠：'+(CURRENT_SCENE.teacher?.specialItem||'保留')+'。';gearDialog.append(gearIntro);
for(const c of CURRENT_SCENE.loadouts){const section=document.createElement('section');const h=document.createElement('h2');h.textContent=c.name+' ／ '+c.game;section.append(h);for(const line of ['所属：'+c.team+' ／ '+c.role,'職業：'+c.job+' ／ Lv.'+c.level,'ステータス：'+Object.entries(c.stats).map(([k,v])=>k+' '+v).join(' ／ '),'体調：'+c.condition,'現在の装備：'+c.gear,'固有スキル：'+c.skill+' — '+c.effect,'特殊アイテム：'+c.item+' — '+c.itemEffect]){const p=document.createElement('p');p.textContent=line;section.append(p)}gearDialog.append(section)}
document.body.append(gearDialog);const gearButton=document.createElement('button');gearButton.textContent='職業・ステータス';gearButton.onclick=()=>gearDialog.showModal();document.querySelector('.player').append(gearButton);

const teamDialog=document.createElement('dialog');teamDialog.className='journal';teamDialog.setAttribute('aria-label','班編成');const tc=document.createElement('button');tc.textContent='閉じる';tc.onclick=()=>teamDialog.close();teamDialog.append(tc);
if(CURRENT_SCENE.expeditionOrganization){const h=document.createElement('h2');h.textContent='現在の任務編成';teamDialog.append(h);for(const g of CURRENT_SCENE.expeditionOrganization.teams){const p=document.createElement('p');p.textContent=g.name+' '+g.members.length+'人：'+g.members.join('・')+' ／ '+g.task;teamDialog.append(p)}const p=document.createElement('p');p.textContent='現在は全33人帰還。最新の出撃人数と役割は物語・作戦地図を参照。以下は元の生活班。';teamDialog.append(p)}
for(const t of CURRENT_SCENE.teams){const h=document.createElement('h2');h.textContent=t.name+' ／ 班長：'+t.leader;teamDialog.append(h);const ul=document.createElement('ul');for(const m of t.members){const li=document.createElement('li');li.textContent=m.role+'：'+m.name;ul.append(li)}teamDialog.append(ul)}const hp=document.createElement('p');hp.textContent='基本の班編成は上記。現在の所在：'+Object.entries(CURRENT_SCENE.deployment?.currentLocations||{}).filter(([,names])=>Array.isArray(names)&&names.length).map(([place,names])=>place+' '+names.length+'人').join('／')+'。その時点の役割と休養は名鑑を参照。';teamDialog.append(hp);document.body.append(teamDialog);const tb=document.createElement('button');tb.textContent='班編成';tb.onclick=()=>teamDialog.showModal();document.querySelector('.player').append(tb);
